{"path": "/private/tmp/prompt_demos/runs_flash-demos/workspaces/04/parser.mbt", "content": "/// A recursive-descent parser for a TOML subset.
priv struct Parser {
  input : String
  mut pos : Int
  mut line : Int
}

/// Utilities — lookahead and advance.
fn Parser::peek(self : Parser) -> Char? {
  if self.pos >= self.input.length() {
    None
  } else {
    Some(self.input[self.pos])
  }
}

fn Parser::advance(self : Parser) -> Char raise TomlError {
  guard let Some(c) = self.peek() else {
    raise TomlError("unexpected end of input")
  }
  self.pos += 1
  if c == '\n' {
    self.line += 1
  }
  c
}

fn Parser::done(self : Parser) -> Bool {
  self.pos >= self.input.length()
}

/// Skip horizontal whitespace (spaces and tabs).
fn Parser::skip_hspace(self : Parser) {
  while self.peek() is Some(c) && (c == ' ' || c == '\t') {
    self.pos += 1
  }
}

/// Skip an entire line (to end-of-line or EOF).
fn Parser::skip_line(self : Parser) {
  while self.peek() is Some(c) && c != '\n' {
    self.pos += 1
  }
}

/// Skip whitespace (including newlines) and comments.
fn Parser::skip_ws_and_comments(self : Parser) {
  loop {
    self.skip_hspace()
    match self.peek() {
      Some('\n') => {
        self.pos += 1
        self.line += 1
      }
      Some('#') => {
        self.skip_line()
      }
      _ => break
    }
  }
}

/// Expect a specific character or raise.
fn Parser::expect(self : Parser, ch : Char) raise TomlError {
  guard let Some(c) = self.peek() else {
    raise TomlError("expected '\{ch}', got end of input")
  }
  if c != ch {
    raise TomlError("expected '\{ch}', got '\{c}'")
  }
  self.pos += 1
}

// ---------------------------------------------------------------------------
// Key parsing
// ---------------------------------------------------------------------------

/// Parse a single bare key segment.
fn Parser::parse_bare_key(self : Parser) -> String raise TomlError {
  let start = self.pos
  while self.peek() is Some(c) && (c.is_alphanum() || c == '_' || c == '-') {
    self.pos += 1
  }
  if self.pos == start {
    raise TomlError("expected a bare key at \{self.position()}")
  }
  self.input[start:self.pos].to_owned()
}

/// Parse a dotted key sequence (one or more bare key segments separated by `.`).
fn Parser::parse_key(self : Parser) -> Array[String] raise TomlError {
  let segments : Array[String] = []
  segments.push(self.parse_bare_key())
  loop {
    self.skip_hspace()
    if self.peek() is Some('.') {
      self.pos += 1
      self.skip_hspace()
      segments.push(self.parse_bare_key())
    } else {
      break
    }
  }
  segments
}

// ---------------------------------------------------------------------------
// Value parsing
// ---------------------------------------------------------------------------

fn Parser::parse_value(self : Parser) -> Json raise TomlError {
  self.skip_hspace()
  match self.peek() {
    Some('"') => self.parse_string()
    Some('t') | Some('f') => self.parse_bool()
    Some('[') => self.parse_array()
    Some(c) if c.is_digit() || c == '-' => self.parse_integer()
    Some(c) => raise TomlError("unexpected '\{c}' at \{self.position()}")
    None => raise TomlError("expected a value, got end of input")
  }
}

/// Parse a basic string with \" \\ \n \t escapes.
fn Parser::parse_string(self : Parser) -> Json raise TomlError {
  self.expect('"')
  let mut buf = StringBuilder::new()
  loop {
    match self.peek() {
      None => raise TomlError("unterminated string at \{self.position()}")
      Some('\n') => raise TomlError("newline in string at \{self.position()}")
      Some('"') => {
        self.pos += 1
        break
      }
      Some('\\') => {
        self.pos += 1
        match self.advance() {
          '"' => buf.write_char('"')
          '\\' => buf.write_char('\\')
          'n' => buf.write_char('\n')
          't' => buf.write_char('\t')
          c => raise TomlError("invalid escape '\\{c}' at \{self.position()}")
        }
      }
      Some(c) => {
        buf.write_char(c)
        self.pos += 1
      }
    }
  }
  Json::string(buf.to_string())
}

/// Parse an integer (positive or negative).
fn Parser::parse_integer(self : Parser) -> Json raise TomlError {
  let start = self.pos
  if self.peek() is Some('-') {
    self.pos += 1
  }
  while self.peek() is Some(c) && c.is_digit() {
    self.pos += 1
  }
  if self.pos == start || (self.pos == start + 1 && self.input[start] == '-') {
    raise TomlError("expected an integer at \{self.position()}")
  }
  let text = self.input[start:self.pos].to_owned()
  let n = @string.parse_int(text) catch {
    _ => raise TomlError("invalid integer literal '\{text}'")
  }
  Json::number(n.to_double(), repr~=text)
}

/// Parse a boolean.
fn Parser::parse_bool(self : Parser) -> Json raise TomlError {
  let start = self.pos
  while self.peek() is Some(c) && c.is_alpha() {
    self.pos += 1
  }
  let text = self.input[start:self.pos].to_owned()
  match text {
    "true" => Json::boolean(true)
    "false" => Json::boolean(false)
    _ => raise TomlError("invalid boolean literal '\{text}'")
  }
}

/// Parse an array of values.
fn Parser::parse_array(self : Parser) -> Json raise TomlError {
  self.expect('[')
  let mut items : Array[Json] = []
  loop {
    self.skip_ws_and_comments()
    match self.peek() {
      Some(']') => {
        self.pos += 1
        break
      }
      _ => {
        items.push(self.parse_value())
        self.skip_ws_and_comments()
        match self.peek() {
          Some(',') => {
            self.pos += 1
          }
          Some(']') => {
            self.pos += 1
            break
          }
          Some(c) => raise TomlError("expected ',' or ']' in array, got '\{c}'")
          None => raise TomlError("unterminated array")
        }
      }
    }
  }
  Json::array(items)
}

// ---------------------------------------------------------------------------
// Document parsing
// ---------------------------------------------------------------------------

/// Set a value at a dotted path inside a JSON object, creating nested objects
/// as needed. Raise TomlError on duplicate key.
fn set_at_path(obj : Map[String, Json], path : Array[String], value : Json) raise TomlError {
  fn go(remaining : ArrayView[String], current : Map[String, Json]) raise TomlError {
    let key = remaining[0]
    if remaining.length() == 1 {
      if current.contains(key) {
        raise TomlError("duplicate key: '\{key}'")
      }
      current[key] = value
    } else {
      let inner = if current.contains(key) {
        match current[key] {
          Json::Object(m) => m
          _ => raise TomlError("key '\{key}' is not a table")
        }
      } else {
        let m : Map[String, Json] = Map::new()
        current[key] = Json::object(m)
        m
      }
      go(remaining[1:], inner)
    }
  }
  go(path[0:], obj)
}

pub fn parse_toml(input : String) -> Json raise TomlError {
  let p = Parser::new(input)
  let root : Map[String, Json] = Map::new()
  let mut current_table_path : Array[String] = []
  p.skip_ws_and_comments()
  while !p.done() {
    match p.peek() {
      Some('[') => {
        // Table header
        p.pos += 1
        if p.peek() is Some('[') {
          raise TomlError("array-of-tables not supported")
        }
        current_table_path = p.parse_key()
        p.skip_hspace()
        p.expect(']')
        p.skip_line()
        p.skip_ws_and_comments()
        // Ensure the table path exists in root
        let _ = set_at_path(root, current_table_path, Json::object(Map::new()))
      }
      Some('#') => {
        p.skip_line()
        p.skip_ws_and_comments()
      }
      Some('\n') => {
        p.pos += 1
        p.line += 1
        p.skip_ws_and_comments()
      }
      _ => {
        // Key-value pair
        let key_segments = p.parse_key()
        p.skip_hspace()
        p.expect('=')
        p.skip_hspace()
        let value = p.parse_value()
        p.skip_line()
        p.skip_ws_and_comments()
        // Compute full path
        let full_path = if current_table_path.is_empty() {
          key_segments
        } else {
          let segs : Array[String] = []
          for s in current_table_path {
            segs.push(s)
          }
          for s in key_segments {
            segs.push(s)
          }
          segs
        }
        set_at_path(root, full_path, value)
      }
    }
  }
  Json::object(root)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// Build an error-context position string.
fn Parser::position(self : Parser) -> String {
  "line \{self.line + 1}"
}

fn Parser::new(input : String) -> Parser {
  { input, pos: 0, line: 0 }
}
"}

