/// Helper: ensure a path exists in the object tree, creating intermediate
/// tables as needed. Used at the start of every table header so subsequent
/// key-value pairs have a home.
fn ensure_path(obj : Map[String, Json], path : Array[String]) -> Map[String, Json] raise TomlError {
  let mut current = obj
  for i in 0..<path.length() {
    let key = path[i]
    if i == path.length() - 1 {
      // Final segment: create or verify table.
      if current.contains(key) {
        match current[key] {
          Json::Object(m) => { current = m }
          _ => raise TomlError("key '\{key}' is not a table")
        }
      } else {
        let m : Map[String, Json] = Map::new()
        current[key] = Json::object(m)
        current = m
      }
    } else {
      // Intermediate segment: descend or create.
      if current.contains(key) {
        match current[key] {
          Json::Object(m) => { current = m }
          _ => raise TomlError("key '\{key}' is not a table")
        }
      } else {
        let m : Map[String, Json] = Map::new()
        current[key] = Json::object(m)
        current = m
      }
    }
  }
  current
}

/// Set a value at a dotted path inside a JSON object, creating nested objects
/// as needed. Raise TomlError on duplicate key.
fn set_value(obj : Map[String, Json], path : Array[String], value : Json) raise TomlError {
