  let parent_key = path[path.length() - 1]
  let mut current = obj
  for i in 0..<path.length() - 1 {
    let key = path[i]
    if current.contains(key) {
      match current[key] {
        Json::Object(m) => { current = m }
        _ => raise TomlError("key '\{key}' is not a table at line \{i + 1}")
      }
    } else {
      let m : Map[String, Json] = Map::new()
      current[key] = Json::object(m)
      current = m
    }
  }
  // Now set the value
  if current.contains(parent_key) {
    raise TomlError("duplicate key: '\{parent_key}'")
  }
  current[parent_key] = value
}

pub fn parse_toml(input : String) -> Json raise TomlError {
  let p = Parser::new(input)
  let root : Map[String, Json] = Map::new()
  let mut current_table : Map[String, Json] = root
  let mut current_path : Array[String] = []
  p.skip_ws_and_comments()
  while !p.done() {
    match p.peek() {
      Some('[') => {
        // Table header
        p.pos += 1
        if p.peek() is Some('[') {
          raise TomlError("array-of-tables not supported")
        }
        let table_path = p.parse_key()
        p.skip_hspace()
        p.expect(']')
        p.skip_line()
        p.skip_ws_and_comments()
        // Ensure the table path exists in root and make it current
        current_path = table_path
        current_table = ensure_path(root, current_path)
      }
      Some('#') => {
        p.skip_line()
        p.skip_ws_and_comments()
      }
      Some('\n') => {
        p.pos += 1
        p.line += 1
        p.skip_ws_and_comments()
      }
      _ => {
        // Key-value pair
        let key_segments = p.parse_key()
        p.skip_hspace()
        p.expect('=')
        p.skip_hspace()
        let value = p.parse_value()
        p.skip_line()
        p.skip_ws_and_comments()
        // Compute full path for duplicate detection and nesting
        let full_path : Array[String] = []
        for s in current_path {
          full_path.push(s)
        }
        for s in key_segments {
          full_path.push(s)
        }
        set_value(root, full_path, value)
      }
    }
  }
  Json::object(root)
}

