}

/// Parse an integer (positive or negative).
fn Parser::parse_integer(self : Parser) -> Json raise TomlError {
  let start = self.pos
  match self.peek() {
    Some('-') => {
      self.pos += 1
    }
    _ => ()
  }
  loop {
    match self.peek() {
      Some(c) if c.is_ascii_digit() => { self.pos += 1 }
      _ => break
    }
