{"content": "/// A recursive-descent parser for a TOML subset.
priv struct Parser {
  input : String
  mut pos : Int
  mut line : Int
}

/// Utilities — lookahead and advance.
fn Parser::peek(self : Parser) -> Char? {
  self.input.get_char(self.pos)
}

fn Parser::advance(self : Parser) -> Char raise TomlError {
  match self.input.get_char(self.pos) {
    Some(c) => {
      self.pos += 1
      if c == '\n' {
        self.line += 1
      }
      c
    }
    None => raise TomlError("unexpected end of input")
  }
}

fn Parser::done(self : Parser) -> Bool {
  self.pos >= self.input.length()
}

/// Skip horizontal whitespace (spaces and tabs).
fn Parser::skip_hspace(self : Parser) -> Unit {
  while true {
    match self.peek() {
      Some(c) if c == ' ' || c == '\t' => {
        self.pos += 1
      }
      _ => break
    }
  }
}

/// Skip an entire line (to end-of-line or EOF).
fn Parser::skip_line(self : Parser) -> Unit {
  while true {
    match self.peek() {
      Some(c) if c != '\n' => {
        self.pos += 1
      }
      _ => break
    }
  }
}

/// Skip whitespace (including newlines) and comments.
fn Parser::skip_ws_and_comments(self : Parser) -> Unit {
  while true {
    self.skip_hspace()
    match self.peek() {
      Some('\n') => {
        self.pos += 1
        self.line += 1
      }
      Some('#') => {
        self.skip_line()
      }
      _ => break
    }
  }
}

/// Expect a specific character or raise.
fn Parser::expect(self : Parser, ch : Char) -> Unit raise TomlError {
  match self.peek() {
    Some(c) if c == ch => {
      self.pos += 1
    }
    Some(c) => raise TomlError("expected '\{ch}', got '\{c}'")
    None => raise TomlError("expected '\{ch}', got end of input")
  }
}

// ---------------------------------------------------------------------------
// Key parsing
// ---------------------------------------------------------------------------

/// Parse a single bare key segment.
fn Parser::parse_bare_key(self : Parser) -> String raise TomlError {
  let start = self.pos
  while true {
    match self.peek() {
      Some(c) if c.is_ascii_alphabetic() || c.is_ascii_digit() || c == '_' || c == '-' => {
        self.pos += 1
      }
      _ => break
    }
  }
  if self.pos == start {
    raise TomlError("expected a bare key at \{self.position()}")
  }
  self.input[start:self.pos].to_owned()
}

/// Parse a dotted key sequence (one or more bare key segments separated by `.`).
fn Parser::parse_key(self : Parser) -> Array[String] raise TomlError {
  let segments : Array[String] = []
  segments.push(self.parse_bare_key())
  while true {
    self.skip_hspace()
    match self.peek() {
      Some('.') => {
        self.pos += 1
        self.skip_hspace()
        segments.push(self.parse_bare_key())
      }
      _ => break
    }
  }
  segments
}

// ---------------------------------------------------------------------------
// Value parsing
// ---------------------------------------------------------------------------

fn Parser::parse_value(self : Parser) -> Json raise TomlError {
  self.skip_hspace()
  match self.peek() {
    Some('"') => self.parse_string()
    Some('t') | Some('f') => self.parse_bool()
    Some('[') => self.parse_array()
    Some(c) if c.is_ascii_digit() || c == '-' => self.parse_integer()
    Some(c) => raise TomlError("unexpected '\{c}' at \{self.position()}")
    None => raise TomlError("expected a value, got end of input")
  }
}

/// Parse a basic string with \" \\ \n \t escapes.
fn Parser::parse_string(self : Parser) -> Json raise TomlError {
  self.expect('"')
  let buf = StringBuilder::new()
  while true {
    match self.peek() {
      None => raise TomlError("unterminated string at \{self.position()}")
      Some('\n') => raise TomlError("newline in string at \{self.position()}")
      Some('"') => {
        self.pos += 1
        break
      }
      Some('\\') => {
        self.pos += 1
        match self.advance() {
          '"' => buf.write_char('"')
          '\\' => buf.write_char('\\')
          'n' => buf.write_char('\n')
          't' => buf.write_char('\t')
          _ => raise TomlError("invalid escape at \{self.position()}")
        }
      }
      Some(c) => {
        buf.write_char(c)
        self.pos += 1
      }
    }
  }
  Json::string(buf.to_string())
}

/// Parse an integer (positive or negative).
fn Parser::parse_integer(self : Parser) -> Json raise TomlError {
  let start = self.pos
  match self.peek() {
    Some('-') => {
      self.pos += 1
    }
    _ => ()
  }
  while true {
    match self.peek() {
      Some(c) if c.is_ascii_digit() => { self.pos += 1 }
      _ => break
    }
  }
  // Check that at least one digit was consumed
  if self.pos == start || (self.pos == start + 1 && self.input.get_char(start) == Some('-')) {
    raise TomlError("expected an integer at \{self.position()}")
  }
  let text = self.input[start:self.pos].to_owned()
  let n = @string.parse_int(text) catch {
    _ => raise TomlError("invalid integer literal '\{text}'")
  }
  Json::number(n.to_double(), repr=text)
}

/// Parse a boolean.
fn Parser::parse_bool(self : Parser) -> Json raise TomlError {
  let start = self.pos
  while true {
    match self.peek() {
      Some(c) if c.is_ascii_alphabetic() => { self.pos += 1 }
      _ => break
    }
  }
  let text = self.input[start:self.pos].to_owned()
  match text {
    "true" => Json::boolean(true)
    "false" => Json::boolean(false)
    _ => raise TomlError("invalid boolean literal '\{text}'")
  }
}

/// Parse an array of values.
fn Parser::parse_array(self : Parser) -> Json raise TomlError {
  self.expect('[')
  let items : Array[Json] = []
  while true {
    self.skip_ws_and_comments()
    match self.peek() {
      Some(']') => {
        self.pos += 1
        break
      }
      _ => {
        items.push(self.parse_value())
        self.skip_ws_and_comments()
        match self.peek() {
          Some(',') => {
            self.pos += 1
          }
          Some(']') => {
            self.pos += 1
            break
          }
          Some(c) => raise TomlError("expected ',' or ']' in array, got '\{c}'")
          None => raise TomlError("unterminated array")
        }
      }
    }
  }
  Json::array(items)
}

// ---------------------------------------------------------------------------
// Document parsing
// ---------------------------------------------------------------------------

/// Return an empty mutable map.
fn empty_map() -> Map[String, Json] {
  Map([], capacity=0)
}

/// Helper: ensure a path exists in the object tree, creating intermediate
/// tables as needed.
fn ensure_path(obj : Map[String, Json], path : Array[String]) -> Map[String, Json] raise TomlError {
  let mut current = obj
  for i in 0..<path.length() {
    let key = path[i]
    if i == path.length() - 1 {
      if current.contains(key) {
        match current[key] {
          Json::Object(m) => { current = m }
          _ => raise TomlError("key '\{key}' is not a table")
        }
      } else {
        let m = empty_map()
        current[key] = Json::object(m)
        current = m
      }
    } else {
      if current.contains(key) {
        match current[key] {
          Json::Object(m) => { current = m }
          _ => raise TomlError("key '\{key}' is not a table")
        }
      } else {
        let m = empty_map()
        current[key] = Json::object(m)
        current = m
      }
    }
  }
  current
}

/// Set a value at a dotted path inside a JSON object, creating nested objects
/// as needed. Raise TomlError on duplicate key.
fn set_value(obj : Map[String, Json], path : Array[String], value : Json) -> Unit raise TomlError {
  let parent_key = path[path.length() - 1]
  let mut current = obj
  let limit = path.length() - 1
  for i in 0..<limit {
    let key = path[i]
    if current.contains(key) {
      match current[key] {
        Json::Object(m) => { current = m }
        _ => raise TomlError("key '\{key}' is not a table")
      }
    } else {
      let m = empty_map()
      current[key] = Json::object(m)
      current = m
    }
  }
  if current.contains(parent_key) {
    raise TomlError("duplicate key: '\{parent_key}'")
  }
  current[parent_key] = value
}

pub fn parse_toml(input : String) -> Json raise TomlError {
  let p = Parser::new(input)
  let root : Map[String, Json] = empty_map()
  let mut current_path : Array[String] = []
  p.skip_ws_and_comments()
  while !p.done() {
    match p.peek() {
      Some('[') => {
        // Table header
        p.pos += 1
        match p.peek() {
          Some('[') => raise TomlError("array-of-tables not supported")
          _ => ()
        }
        let table_path = p.parse_key()
        p.skip_hspace()
        p.expect(']')
        p.skip_line()
        p.skip_ws_and_comments()
        current_path = table_path
        let _ = ensure_path(root, current_path)
      }
      Some('#') => {
        p.skip_line()
        p.skip_ws_and_comments()
      }
      Some('\n') => {
        p.pos += 1
        p.line += 1
        p.skip_ws_and_comments()
      }
      _ => {
        // Key-value pair
        let key_segments = p.parse_key()
        p.skip_hspace()
        p.expect('=')
        p.skip_hspace()
        let value = p.parse_value()
        p.skip_line()
        p.skip_ws_and_comments()
        // Compute full path for duplicate detection and nesting
        let full_path : Array[String] = []
        for s in current_path {
          full_path.push(s)
        }
        for s in key_segments {
          full_path.push(s)
        }
        set_value(root, full_path, value)
      }
    }
  }
  Json::object(root)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/// Build an error-context position string.
fn Parser::position(self : Parser) -> String {
  "line \{self.line + 1}"
}

fn Parser::new(input : String) -> Parser {
  { input, pos: 0, line: 0 }
}
